async def act(page):
    import asyncio
    from urllib.parse import urljoin

    # 1) Try to dismiss any overlay/modal that could block clicks
    try:
        await page.keyboard.press("Escape")
        await asyncio.sleep(0.25)
    except Exception:
        pass

    # 2) Locate main region and wait for it defensively
    main = page.get_by_role("main")
    try:
        await main.wait_for()
    except Exception:
        try:
            await page.wait_for_load_state("networkidle")
        except Exception:
            pass

    # 3) Locate article results and ensure we count before indexing
    articles = main.get_by_role("article")
    article_count = await articles.count()
    if article_count == 0:
        return

    last_index = article_count - 1
    last_article = articles.nth(last_index)

    # 4) Prefer the link inside the article's heading
    link_to_click = None
    if await last_article.get_by_role("heading").count() > 0:
        heading0 = last_article.get_by_role("heading").nth(0)
        if await heading0.get_by_role("link").count() > 0:
            link_to_click = heading0.get_by_role("link").nth(0)

    if link_to_click is None:
        # Fallback: first link inside the article
        article_links = last_article.get_by_role("link")
        if await article_links.count() == 0:
            return
        link_to_click = article_links.nth(0)

    # 5) Attempt to click the chosen link. If blocked, attempt remediation and fallbacks.
    try:
        await link_to_click.click()
        return
    except Exception:
        # Remove common overlay/modal elements and restore pointer events
        try:
            await page.evaluate("""() => {
                const selectors = [
                    '.overlay', '.modal', '.mfp-wrap', '.popup', '.popup-wrapper',
                    '.modal-backdrop', '[role="dialog"]', '#popup', '.fancybox-overlay', '.ui-widget-overlay'
                ];
                selectors.forEach(s => document.querySelectorAll(s).forEach(e => e.remove()));
                try { document.body.style.pointerEvents = 'auto'; } catch(e){}
            }""")
            await asyncio.sleep(0.25)
        except Exception:
            pass

        # Try a JS click on the element handle
        handle = await link_to_click.element_handle()
        if handle is not None:
            try:
                await page.evaluate("el => el.click()", handle)
                return
            except Exception:
                try:
                    href = await handle.get_attribute("href")
                    if href:
                        dest = urljoin(page.url, href)
                        await page.goto(dest)
                        return
                except Exception:
                    pass

    # If all retries failed, give up silently
    return

